if(!Session::isLoggedIn()){header('Location: '.APP_URL.'index.php');exit();}$role=Session::getUserRole();$uid=(int)Session::getUserId();if($role!=='supervisor'){header('Location: '.APP_URL.'index.php');exit();}$pageTitle='تسجيل دفعة لصالح فينا الخير';$active='transactions';$errors=[];$monthOptions=[];for($i=-24;$i<=12;$i++)$monthOptions[]=date('F/Y',strtotime(date('Y-m-01')." $i months"));$currentMonth=date('F/Y');
$mySponsors=[];$rows=dbFetchAll("SELECT id,full_name,sponsor_code,supervisor_id,first_letter_id,gender FROM sponsors WHERE first_letter_id IN (SELECT letter_id FROM supervisor_letters WHERE supervisor_id=?) ORDER BY full_name",[$uid]);foreach($rows as $row)if(supervisorCanAccessSponsor($uid,$row))$mySponsors[]=$row;$mySponsorIds=array_map('intval',array_column($mySponsors,'id'));$ships=[];if($mySponsorIds){$ph=implode(',',array_fill(0,count($mySponsorIds),'?'));$ships=dbFetchAll("SELECT sp.id,sp.sponsor_id,sp.sponsorship_code,sp.monthly_amount,sp.currency_code,s.full_name sponsor_name,fc.child_name FROM sponsorships sp JOIN sponsors s ON s.id=sp.sponsor_id LEFT JOIN family_children fc ON fc.id=sp.child_id WHERE sp.status='active' AND sp.sponsor_id IN ($ph) ORDER BY s.full_name,sp.id",$mySponsorIds);}
$input=['sponsor_id'=>(int)($_GET['sponsor_id']??0),'sponsorship_id'=>(int)($_GET['sponsorship_id']??0),'type'=>'monthly_sponsorship','month'=>$currentMonth,'amount'=>'','fina_share'=>'','method'=>'cash','date'=>date('Y-m-d'),'purpose_note'=>'','description'=>''];
if($_SERVER['REQUEST_METHOD']==='POST'){$input['sponsor_id']=(int)($_POST['sponsor_id']??0);$input['sponsorship_id']=(int)($_POST['sponsorship_id']??0);$input['type']=$_POST['type']??'monthly_sponsorship';$input['month']=trim($_POST['month']??'');$input['amount']=trim($_POST['amount']??'');$input['fina_share']=trim($_POST['fina_share']??'');$input['method']=$_POST['method']??'cash';$input['date']=trim($_POST['date']??'')?:date('Y-m-d');$input['purpose_note']=trim($_POST['purpose_note']??'');$input['description']=trim($_POST['description']??'');if(!verify_csrf())$errors[]='انتهت صلاحية الجلسة.';$sponsor=$input['sponsor_id']>0?dbFetchOne("SELECT id,full_name,sponsor_code,supervisor_id,first_letter_id,gender FROM sponsors WHERE id=?",[$input['sponsor_id']]):null;if($input['sponsor_id']<=0||!$sponsor||!supervisorCanAccessSponsor($uid,$sponsor))$errors[]='هذا الكفيل خارج نطاق إشرافك.';$ship=$input['sponsorship_id']>0?dbFetchOne("SELECT id,sponsor_id,monthly_amount,status,currency_code FROM sponsorships WHERE id=?",[$input['sponsorship_id']]):null;if($input['type']==='monthly_sponsorship'){if(!$ship)$errors[]='اختر الكفالة المرتبطة بالدفعة.';elseif((int)$ship['sponsor_id']!==$input['sponsor_id'])$errors[]='الكفالة لا تخص الكفيل المحدد.';elseif($ship['status']!=='active')$errors[]='الكفالة المحددة غير نشطة.';if(!in_array($input['month'],$monthOptions,true))$errors[]='الشهر المحدد غير صالح.';}if(!in_array($input['type'],['monthly_sponsorship','general_donation','project_donation','other'],true))$errors[]='نوع الدفعة غير صالح.';$amount=round((float)str_replace(',','',$input['amount']),2);$finaShare=round((float)str_replace(',','',$input['fina_share']),2);if($amount<=0)$errors[]='إجمالي الدفعة يجب أن يكون أكبر من صفر.';if($finaShare<0||$finaShare>$amount)$errors[]='حصة فينا الخير يجب أن تكون بين صفر وإجمالي الدفعة.';if(!in_array($input['method'],['cash','bank_transfer','credit_card','mobile','other'],true))$errors[]='طريقة الدفع غير صالحة.';if(!preg_match('/^\d{4}-\d{2}-\d{2}