if(!$errors){$mode=$finaShare<=0?'ahl_only':($finaShare>=$amount?'fina_only':'shared');try{db()->beginTransaction();dbExecute("INSERT INTO sponsor_payments (sponsorship_id,supervisor_id,payment_type,sponsor_id,project_id,other_source_note,purpose_note,payment_period,payment_date,amount,currency_code,payment_method,receipt_file_path,notes,status) VALUES (?,?,?,?,NULL,NULL,?,?,?,?,?,?,?,?,'pending')",[$ship['id']??null,$uid,$input['type'],$input['sponsor_id'],$input['purpose_note']!==''?$input['purpose_note']:null,$input['type']==='monthly_sponsorship'?$input['month']:null,$input['date'],$amount,$ship['currency_code']??'SDG',$input['method'],$receiptPath,$input['description']!==''?$input['description']:null]);$spId=(int)dbLastInsertId();if($spId<=0)throw new RuntimeException('تعذر إنشاء سجل التحصيل.');dbExecute("INSERT INTO fina_payment_intakes (sponsor_payment_id,allocation_mode,fina_share_amount,integration_reference,created_by) VALUES (?,?,?,?,?)",[$spId,$mode,$finaShare,'FINA-INTAKE-SP-'.$spId,$uid]);db()->commit();flash('success','تم تسجيل دفعة فينا الخير وإرسالها للمدير المالي للمراجعة.');header('Location: '.APP_URL.'modules/accounting/fina_payment_review.php');exit();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();if($receiptPath&&is_file(dirname(__DIR__,2).'/'.$receiptPath))@unlink(dirname(__DIR__,2).'/'.$receiptPath);$errors[]='تعذر حفظ دفعة فينا الخير بشكل ذري. لم يتم حفظ أي جزء من العملية.';}}}
include dirname(__DIR__,2).'/includes/header.php';?>
<div class="welcome-section fade-in"><h2><i class="fas fa-hand-holding-dollar me-2"></i>تسجيل دفعة لصالح فينا الخير</h2><p>يسجل المشرف التحصيل والتخصيص فقط. لا يتم إنشاء قيد محاسبي هنا؛ الاعتماد والترحيل من مسؤولية المدير المالي.</p></div><?php include dirname(__DIR__,2).'/includes/alerts.php';?><?php if($errors):?><div class="alert alert-danger"><ul class="mb-0"><?php foreach($errors as $e):?><li><?php echo e($e);?></li><?php endforeach;?></ul></div><?php endif;?><div class="card fade-in"><div class="card-header text-white" style="background:#1b4d8f">تفاصيل التحصيل والتخصيص</div><div class="card-body"><form method="post" enctype="multipart/form-data"><?php echo csrf_field();?><div class="row g-3"><div class="col-md-6"><label class="form-label">الكفيل *</label><select name="sponsor_id" id="sponsorId" class="form-select" required><option value="">— اختر —</option><?php foreach($mySponsors as $s):?><option value="<?php echo(int)$s['id'];?>" <?php echo $input['sponsor_id']===(int)$s['id']?'selected':'';?>><?php echo e($s['full_name']);?> — <?php echo e($s['sponsor_code']);?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">نوع الدفعة *</label><select name="type" id="paymentType" class="form-select"><option value="monthly_sponsorship">كفالة شهرية</option><option value="general_donation">تبرع عام</option><option value="project_donation">تبرع مشروع</option><option value="other">أخرى</option></select></div><div class="col-md-6" id="sponsorshipBox"><label class="form-label">الكفالة *</label><select name="sponsorship_id" id="sponsorshipId" class="form-select"><option value="">— اختر الكفالة —</option><?php foreach($ships as $sh):?><option value="<?php echo(int)$sh['id'];?>" data-sponsor="<?php echo(int)$sh['sponsor_id'];?>" data-amount="<?php echo(float)$sh['monthly_amount'];?>" <?php echo $input['sponsorship_id']===(int)$sh['id']?'selected':'';?>><?php echo e($sh['sponsor_name']);?> — <?php echo e($sh['child_name']??'');?> (<?php echo e($sh['sponsorship_code']);?>)</option><?php endforeach;?></select></div><div class="col-md-6" id="monthBox"><label class="form-label">عن شهر *</label><select name="month" class="form-select"><?php foreach($monthOptions as $m):?><option value="<?php echo e($m);?>" <?php echo $input['month']===$m?'selected':'';?>><?php echo e($m);?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">إجمالي ما دفعه الكفيل *</label><input type="number" step="0.01" min="0.01" name="amount" id="grossAmount" class="form-control" required value="<?php echo e($input['amount']);?>"></div><div class="col-md-4"><label class="form-label">المخصص لـ فينا الخير *</label><input type="number" step="0.01" min="0" name="fina_share" id="finaShare" class="form-control" required value="<?php echo e($input['fina_share']);?>"></div><div class="col-md-4"><label class="form-label">حصة أهل الخير</label><input type="text" id="ahlShare" class="form-control" readonly></div><div class="col-md-4"><label class="form-label">طريقة الدفع</label><select name="method" class="form-select"><option value="cash">نقدي / كاش</option><option value="bank_transfer">تحويل بنكي</option><option value="mobile">محفظة إلكترونية</option><option value="credit_card">بطاقة</option><option value="other">أخرى</option></select></div><div class="col-md-4"><label class="form-label">تاريخ التحصيل *</label><input type="date" name="date" class="form-control" required value="<?php echo e($input['date']);?>"></div><div class="col-md-4"><label class="form-label">إيصال التحصيل</label><input type="file" name="receipt_file" class="form-control" accept=".jpg,.jpeg,.png,.pdf"><div class="form-text">JPG / PNG / PDF حتى 10MB.</div></div><div class="col-12"><label class="form-label">ملاحظات</label><textarea name="description" class="form-control" rows="2"><?php echo e($input['description']);?></textarea></div><div class="col-12"><label class="form-label">توضيح الغرض / التخصيص</label><input type="text" name="purpose_note" class="form-control" value="<?php echo e($input['purpose_note']);?>"></div><div class="col-12"><div class="alert alert-warning mb-0"><strong>تنبيه محاسبي:</strong> حصة فينا الخير تسجل كأموال طرف ثالث مستحقة لـ فينا الخير، وليست إيراداً لأهل الخير. الرسوم الإدارية — إن انطبقت — تحسب على حصة أهل الخير فقط.</div></div></div><div class="mt-4"><button class="btn btn-primary btn-lg"><i class="fas fa-paper-plane me-1"></i> إرسال للمدير المالي</button></div></form></div></div><script>
function refreshShips(){const sid=document.getElementById('sponsorId').value;const sel=document.getElementById('sponsorshipId');Array.from(sel.options).forEach(o=>{if(o.value)o.hidden=o.dataset.sponsor!==sid;});if(sel.selectedOptions[0]&&sel.selectedOptions[0].hidden)sel.value='';}function calc(){const a=parseFloat(document.getElementById('grossAmount').value)||0;const f=parseFloat(document.getElementById('finaShare').value)||0;document.getElementById('ahlShare').value=Math.max(0,a-f).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});}document.getElementById('sponsorId').addEventListener('change',refreshShips);document.getElementById('grossAmount').addEventListener('input',calc);document.getElementById('finaShare').addEventListener('input',calc);document.getElementById('paymentType').addEventListener('change',function(){const m=this.value==='monthly_sponsorship';document.getElementById('sponsorshipBox').style.display=m?'':'none';document.getElementById('monthBox').style.display=m?'':'none';});refreshShips();calc();document.getElementById('paymentType').dispatchEvent(new Event('change'));
</script><?php include dirname(__DIR__,2).'/includes/footer.php';?>
